const {
  departureLocation,
  destinationCity,
  accommodationType,
  amenities,
  bedrooms,
  bathrooms,
  startDate,
  endDate,
  tripType,
  groupSize,
  ageRange,
  budget,
  email
} = $json;
console.log('Preparing prompt with departureLocation:', departureLocation);
return [{ json: {
  departureLocation,
  destinationCity,
  accommodationType,
  amenities,
  bedrooms,
  bathrooms,
  startDate,
  endDate,
  tripType,
  groupSize,
  ageRange,
  budget,
  email,
  prompt: `You are an experienced and helpful AI travel agent specializing in Airbnb and hotel stays. Your goal is to create exciting, practical, and well-organized travel itineraries tailored to each user's preferences. Be friendly, informative, and concise.
- Departure Location: ${departureLocation}
- Destination: ${destinationCity}
- Accommodation Type: ${accommodationType}
- Key Amenities: ${Array.isArray(amenities) ? amenities.join(', ') : amenities || 'Not specified'}
- Number of Bedrooms: ${bedrooms}
- Number of Bathrooms: ${bathrooms}
- Travel Dates: ${startDate} to ${endDate}
- Trip Type: ${tripType}
- Group Size: ${groupSize}
- Age Ranges: ${Array.isArray(ageRange) ? ageRange.join(', ') : ageRange || 'Not specified'}
- Budget: $${budget}

Create a complete itinerary for this trip focusing on an Airbnb or hotel stay. Include recommendations for:
1. Flights (specific airlines and routes from ${departureLocation || 'the nearest major airport'} to ${destinationCity}, with estimated costs)
2. Accommodation options (specific Airbnb listings or hotels matching the accommodation type, amenities, and room preferences; include estimated cost per night and total cost for the trip, and provide at least one alternative option)
3. Daily schedule with activities, dining options, and sights (include morning, afternoon, and evening plans for each day)
4. Estimated food budget (daily cost and recommendations for dining, considering local cuisine)
5. A cost summary table (flights, accommodation, activities, food, total, and remaining budget). This section is mandatory and must always be included. If no costs are available, use placeholder values (e.g., Flights\t$0). Ensure the table includes all categories: Flights, Accommodation, Activities, Food, Total, and Remaining Budget, in that order.
6. Travel tips specific to the destination and Airbnb/hotel experience

Respond in a clean and organized layout with sections. Include hyperlinks to Airbnb listings, hotels, activities, or dining options where relevant, using <a href="URL">Description</a> format. Use real, functional URLs where users can book or learn more (e.g., Airbnb, hotel websites, attraction sites). Do not use placeholder URLs like "https://example.com". Ensure the Cost Summary section is formatted as a tab-separated table (e.g., Flights\t$1,000).` }
}];

const airbnb = $node['Prepare Airbnb Data'].json;
const ai = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output:', ai);
return [{ json: {
  departureLocation: airbnb.departureLocation,
  destinationCity: airbnb.destinationCity,
  accommodationType: airbnb.accommodationType,
  amenities: airbnb.amenities,
  bedrooms: airbnb.bedrooms,
  bathrooms: airbnb.bathrooms,
  startDate: airbnb.startDate,
  endDate: airbnb.endDate,
  tripType: airbnb.tripType,
  groupSize: airbnb.groupSize,
  ageRange: airbnb.ageRange,
  budget: airbnb.budget,
  email: airbnb.email,
  itinerary: ai
} }];

const destination = $json.destinationCity || 'Your Destination';
const travelDates = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const departure = $json.departureLocation || 'Not specified';
const accommodationType = $json.accommodationType || 'Not specified';
const amenities = Array.isArray($json.amenities) ? $json.amenities.join(', ') : $json.amenities || 'Not specified';
const bedrooms = $json.bedrooms || 'Not specified';
const bathrooms = $json.bathrooms || 'Not specified';
const tripType = $json.tripType || 'N/A';
const groupSize = $json.groupSize || 'N/A';
const ageRange = Array.isArray($json.ageRange) ? $json.ageRange.join(', ') : $json.ageRange || 'Not specified';
const budget = $json.budget || 'N/A';
let itineraryRaw = $json.itinerary || 'Itinerary details not available.';
console.log('Initial itineraryRaw:', itineraryRaw);
console.log('Checking for Cost Summary in itineraryRaw (case-insensitive)...');
if (!itineraryRaw.toLowerCase().includes('cost summary:')) {
  console.log('Cost Summary missing, adding fallback');
  itineraryRaw += '\n\nCost Summary:\nFlights\t$0\nAccommodation\t$0\nActivities\t$0\nFood\t$0\n<strong>Total</strong>\t<strong>$0</strong>\n<strong>Remaining Budget</strong>\t<strong>$' + budget + '</strong>';
} else {
  console.log('Cost Summary found in itineraryRaw');
}
console.log('itineraryRaw after fallback check:', itineraryRaw);
const itineraryLines = itineraryRaw.split('\n');
let itinerary = '';
let inTable = false;
let tableRows = [];
for (let line of itineraryLines) {
  line = line.trim();
  if (!line) {
    itinerary += '<br>';
    continue;
  }
  if (line.toLowerCase().startsWith('cost summary:')) {
    inTable = true;
    tableRows = [];
    itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    continue;
  }
  if (inTable && (line.startsWith('Total') || line.startsWith('Remaining Budget'))) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && line.includes('\t')) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && !line.includes('\t')) {
    inTable = false;
    itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
  }
  if (!inTable) {
    if (line.endsWith(':')) {
      itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    } else {
      itinerary += line + '<br>';
    }
  }
}
if (inTable) {
  itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
}
console.log('Final itinerary HTML:', itinerary);
const subject = `Your Airbnb & Hotel Itinerary for ${destination} - Voyage Genie`;
const message = `<div style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f7f7f7; padding: 25px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);"><div style="background-color: #2a4a6e; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;"><h1 style="color: #ffffff; margin: 0; font-size: 28px;">🏠 Your Airbnb & Hotel Itinerary</h1></div><div style="padding: 25px; background-color: #ffffff; border-radius: 0 0 10px 10px;"><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Departing from: ${departure}</h2><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Destination: ${destination}</h2><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Travel Dates:</strong> ${travelDates}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Accommodation Type:</strong> ${accommodationType}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Key Amenities:</strong> ${amenities}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Number of Bedrooms:</strong> ${bedrooms}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Number of Bathrooms:</strong> ${bathrooms}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Trip Type:</strong> ${tripType}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Age Range:</strong> ${ageRange}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Budget:</strong> $${budget} (for ${groupSize} travelers)</p><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><h3 style="color: #2a4a6e; font-size: 18px; margin: 0 0 15px 0; text-align: left;">Itinerary Details</h3><div style="background-color: #f9f9f9; padding: 20px; border-radius: 6px; font-size: 14px; line-height: 1.6; color: #333333;">${itinerary}</div><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><p style="color: #666666; font-size: 12px; text-align: center; margin: 0;">Generated by <strong>Voyage Genie</strong> 🌟</p></div></div>`;

const sessionId = Date.now().toString();
console.log('Returning itineraryHtml directly with sessionId:', sessionId);

return [{ json: { sessionId: sessionId, itineraryHtml: message, resolvedEmail: $json.email || 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message, formData: { departureLocation: departure, destinationCity: destination, startDate: $json.startDate, endDate: $json.endDate, budget: budget, groupSize: groupSize } } }];

const url = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const payload = {
  resolvedEmail: $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage
};
try {
  const response = await $http({
    method: 'POST',
    url: url,
    body: payload,
    headers: { 'Content-Type': 'application/json' }
  });
  console.log('Email trigger response:', response);
} catch (error) {
  console.error('Error triggering email workflow:', error.message);
}
return $input.all();

console.log('Request Details:', JSON.stringify($json, null, 2));
let method = $json.method;
if (!method) {
  method = $json.headers[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// === Extract raw itinerary content from OpenAI response ===
const itineraryRaw = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output:', itineraryRaw);

// === Initialize parsing variables ===
const itineraryLines = itineraryRaw.split('\n');
let formattedItinerary = '';
let inDailySchedule = false;
let inCostSummary = false;
let scheduleLines = [];
let costSummaryRows = [];

// === Helper: Format Daily Schedule block ===
const formatDailySchedule = (lines) => {
  let output = 'Daily Schedule:<br>';
  const joined = lines.join(' ');
  const daySections = joined.match(/(Day \d+:.*?)(?=(Day \d+:|$))/g);

  if (!daySections) return '';

  daySections.forEach((dayMatch, index) => {
    const dayLabelMatch = dayMatch.match(/(Day \d+:.*?)(?=-|$)/);
    if (!dayLabelMatch) return;

    const dayLabel = dayLabelMatch[1].trim();
    const subItems = dayMatch.match(/- (Morning|Afternoon|Evening):.*?(?=(Day \d+:|- (Morning|Afternoon|Evening):|$))/g);

    output += `<strong>${dayLabel}</strong>`;
    if (subItems) {
      const content = subItems.map(item => item.trim()).join('<br>').replace(/^<br>/, '');
      output += `<div class="schedule-day-content">${content}</div>`;
    }

    if (index < daySections.length - 1) output += '<br>';
  });

  return output + '<br>';
};

// === Parse itinerary line-by-line ===
for (let line of itineraryLines) {
  line = line.trim();

  if (!line) {
    if (inDailySchedule) {
      formattedItinerary += formatDailySchedule(scheduleLines);
      inDailySchedule = false;
    } else if (inCostSummary) {
      inCostSummary = false;
      formattedItinerary += `
        <table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">
          ${costSummaryRows.join('')}
        </table><br>`;
      costSummaryRows = [];
    } else {
      formattedItinerary += '<br>';
    }
    continue;
  }

  const lower = line.toLowerCase();

  if (lower.startsWith('daily schedule:')) {
    inDailySchedule = true;
    scheduleLines = [];
    continue;
  }

  if (inDailySchedule) {
    scheduleLines.push(line);
    continue;
  }

  // === Handle Cost Summary Table ===
  if (lower.startsWith('cost summary:')) {
    formattedItinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    inCostSummary = true;
    continue;
  }

  if (inCostSummary && line.includes('\t')) {
    const [category, cost] = line.split('\t').map(str => str.trim());
    const isBold = line.startsWith('Total') || line.startsWith('Remaining Budget');
    const cellStyle = isBold
      ? 'border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;'
      : 'border: 1px solid #e0e0e0; padding: 8px;';
    costSummaryRows.push(`
      <tr>
        <td style="${cellStyle}">${category}</td>
        <td style="${cellStyle}">${cost}</td>
      </tr>`);
    continue;
  }

  // === Close Cost Summary table if next line is non-tab content ===
  if (inCostSummary) {
    inCostSummary = false;
    formattedItinerary += `
      <table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">
        ${costSummaryRows.join('')}
      </table><br>`;
    costSummaryRows = [];
  }

  if (line.endsWith(':')) {
    formattedItinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
  } else {
    formattedItinerary += `${line}<br>`;
  }
}

// === Final check: handle Daily Schedule if it's the last section ===
if (inDailySchedule) {
  formattedItinerary += formatDailySchedule(scheduleLines);
}

// === Final check: handle Cost Summary if it's the last section ===
if (costSummaryRows.length > 0) {
  formattedItinerary += `
    <table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">
      ${costSummaryRows.join('')}
    </table><br>`;
}

console.log('Formatted itinerary:', formattedItinerary);

// === Return updated itinerary in output JSON ===
return [{
  json: {
    ...$json,
    itinerary: formattedItinerary,
  }
}];
